//! The parameters the date objects report for their methods (`Object::method_params()`), which the engine checks
//! named arguments against as it sends them (`zend_handle_named_arg()`), against PHP 8.5.13's arginfo read with
//! Reflection (`tests/vectors/method_params.json`, generated by `method_params.gen.php`; regenerate with
//! `crates/twig-date/tests/vectors/regen.sh method_params`).

mod common;

use common::*;
use serde_json::Value as Json;
use twig_date::{DateObject, DatePeriodObject, IntervalObject, TimeZoneObject, classes};
use twig_value::object::{CallArgs, MethodParams};
use twig_value::{Array, ArrayKey, ObjectRef, PhpString, Value};

/// One object of each class of the vectors, built like the generator builds them.
fn objects(c: &Ctx) -> Vec<(&'static str, ObjectRef)> {
    let date = |class, s: &str| DateObject::construct(&c.ctx, class, s.as_bytes(), None).unwrap();
    let start = date(classes::datetime_immutable(), "2020-01-01");
    let interval = IntervalObject::construct(&c.ctx, b"P1D").unwrap();
    let period = DatePeriodObject::with_recurrences(&c.ctx, &start, &interval, 2, 0).unwrap();
    let iterator = obj(call(&period, "getIterator", vec![], &mut Vec::new()).unwrap());
    vec![
        ("DateTime", date(classes::datetime(), "2020-01-02 03:04:05")),
        (
            "DateTimeImmutable",
            date(classes::datetime_immutable(), "2020-01-02 03:04:05"),
        ),
        (
            "DateTimeZone",
            TimeZoneObject::construct(&c.ctx, b"Europe/Vilnius").unwrap(),
        ),
        ("DateInterval", interval),
        ("DatePeriod", period),
        ("InternalIterator", iterator),
    ]
}

/// A scalar default of the vectors as a value.
fn default_value(v: &Json) -> Value {
    match v {
        Json::Null => Value::Null,
        Json::Bool(b) => Value::Bool(*b),
        Json::Number(n) => Value::Int(n.as_i64().expect("integer default")),
        Json::String(s) => Value::from(s.as_str()),
        other => panic!("default {other}"),
    }
}

/// Every public method reports its parameters, named, ordered and defaulted as PHP declares them. A parameter
/// that is optional without a known default (`UNKNOWN` in the stub: `DatePeriod::__construct()`'s `$interval`,
/// `$end`, `$options`) is reported without a default.
#[test]
fn method_params_match_php_arginfo() {
    let c = Ctx::new();
    let v = load("method_params");
    let objects = objects(&c);
    let classes = v["classes"].as_array().unwrap();
    assert_eq!(classes.len(), objects.len());
    for (entry, (class, object)) in classes.iter().zip(&objects) {
        assert_eq!(s(&entry[0]), *class);
        assert_eq!(object.class_name(), *class);
        let methods = entry[1].as_array().unwrap();
        let names: Vec<String> = object
            .class()
            .public_method_names()
            .iter()
            .map(|m| m.to_string())
            .collect();
        let expected: Vec<&str> = methods.iter().map(|m| s(&m[0])).collect();
        assert_eq!(names, expected, "{class}: get_class_methods()");
        for method in methods {
            let name = s(&method[0]);
            let what = format!("{class}::{name}");
            let reported: MethodParams = object
                .method_params(name)
                .unwrap_or_else(|| panic!("{what}: no parameters reported"));
            let params = method[2].as_array().unwrap();
            let names: Vec<&str> = reported.params.iter().map(|p| p.name).collect();
            let expected: Vec<&str> = params.iter().map(|p| s(&p[0])).collect();
            assert_eq!(names, expected, "{what}: names");
            for (param, php) in reported.params.iter().zip(params) {
                assert!(!param.variadic, "{what}: ${} variadic", param.name);
                let default = php[2].get("value").map(default_value);
                match (&param.default, default) {
                    (None, None) => {}
                    (Some(rs), Some(php)) => {
                        assert!(
                            twig_value::compare::identical(rs, &php),
                            "{what}: ${} default {rs:?}, PHP {php:?}",
                            param.name
                        );
                    }
                    (rs, php) => panic!("{what}: ${} default {rs:?}, PHP {php:?}", param.name),
                }
            }
        }
    }
}

/// `$object->$method(...$spread)` with a string key before an int key fails while the arguments are sent: at an
/// unknown name (`Unknown named parameter $zz`), else at the positional element after a declared name. With the
/// reported parameters the engine fails the same way (`MethodParams::unpack`), before the method is called.
#[test]
fn unpacking_checks_named_elements_as_php_sends_them() {
    let c = Ctx::new();
    let v = load("method_params");
    let objects = objects(&c);
    for case in v["unpack"].as_array().unwrap() {
        let (class, method) = (s(&case[0]), s(&case[1]));
        let object = &objects.iter().find(|(name, _)| *name == class).unwrap().1;
        let mut spread = Array::new();
        for pair in case[2].as_array().unwrap() {
            let key = match &pair[0] {
                Json::Number(n) => ArrayKey::Int(n.as_i64().unwrap()),
                key => ArrayKey::Str(PhpString::from(s(key))),
            };
            spread.insert(key, Value::Int(i(&pair[1])));
        }
        let params = object.method_params(method).unwrap();
        let mut diags = Vec::new();
        let result = match params.unpack(&Value::Array(spread), &mut diags) {
            Ok(args) => format!("no error ({args:?})"),
            Err(e) => exc(&e),
        };
        assert_eq!(result, s(&case[3]), "{class}::{method}({})", case[2]);
        assert!(diags.is_empty(), "{class}::{method}: {diags:?}");
    }
}

/// The methods bind their arguments to the parameters they report: a named argument goes to its parameter, a
/// skipped optional one takes its default, and an unknown name fails before anything runs.
#[test]
fn methods_bind_their_reported_parameters() {
    let c = Ctx::new();
    let objects = objects(&c);
    let date = &objects[0].1;
    let mut diags = Vec::new();
    // setTime(int $hour, int $minute, int $second = 0, int $microsecond = 0)
    let args = CallArgs::new().arg(1).arg(2).named_arg("microsecond", 5);
    date.call_method("setTime", args, &mut diags).unwrap();
    let formatted = date
        .call_method(
            "format",
            CallArgs::new().named_arg("format", "H:i:s.u"),
            &mut diags,
        )
        .unwrap();
    assert_eq!(formatted, Value::from("01:02:00.000005"));
    let error = date
        .call_method(
            "setTime",
            CallArgs::new().named_arg("minute", 5),
            &mut diags,
        )
        .unwrap_err();
    assert_eq!(
        exc(&error),
        "ArgumentCountError: DateTime::setTime(): Argument #1 ($hour) not passed"
    );
    // DateTimeZone::listIdentifiers(int $timezoneGroup = DateTimeZone::ALL, ?string $countryCode = null)
    let timezone = &objects[2].1;
    let args = CallArgs::new()
        .named_arg("countryCode", "LT")
        .named_arg("timezoneGroup", 4096);
    let ids = timezone
        .call_method("listIdentifiers", args, &mut diags)
        .unwrap();
    assert_eq!(
        ids,
        Value::Array(Array::from_values([Value::from("Europe/Vilnius")]))
    );
    // InternalIterator::key()
    let iterator = &objects[5].1;
    let error = iterator
        .call_method("key", CallArgs::new().named_arg("x", 1), &mut diags)
        .unwrap_err();
    assert_eq!(exc(&error), "Error: Unknown named parameter $x");
    assert!(diags.is_empty(), "{diags:?}");
}
